import * as THREE from 'three';

/** Shared time uniform, updated once per frame. */
export const timeU = { value: 0 };

export function makeRand(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Height of the sandy seabed (ripples on top of low dunes). */
export function groundY(x: number, z: number): number {
  const w = x * 0.9 + z * 0.35 + 1.3 * Math.sin(z * 0.3 + x * 0.12);
  const ripple = Math.sin(w * 2.6) * 0.075 + Math.sin((x * 0.25 - z * 0.7) * 2.1 + 1.0) * 0.025;
  const dune = 0.35 * Math.sin(x * 0.13 + 0.5) * Math.cos(z * 0.11) + 0.15 * Math.sin(x * 0.31 + z * 0.23);
  return ripple + dune;
}

export function paint(g: THREE.BufferGeometry, c: THREE.Color): THREE.BufferGeometry {
  const n = g.getAttribute('position').count;
  const arr = new Float32Array(n * 3);
  for (let i = 0; i < n; i++) {
    arr[i * 3] = c.r;
    arr[i * 3 + 1] = c.g;
    arr[i * 3 + 2] = c.b;
  }
  g.setAttribute('color', new THREE.BufferAttribute(arr, 3));
  return g;
}

const CAUSTIC_FN = /* glsl */ `
float causticPattern(vec2 p, float t) {
  vec2 i = p;
  float c = 1.0;
  const float inten = 0.008;
  for (int n = 0; n < 4; n++) {
    float tt = t * (1.0 - 3.5 / float(n + 1));
    i = p + vec2(cos(tt - i.x) + sin(tt + i.y), sin(tt - i.y) + cos(tt + i.x));
    c += 1.0 / length(vec2(p.x / (sin(i.x + tt) / inten), p.y / (cos(i.y + tt) / inten)));
  }
  c /= 4.0;
  c = 1.17 - pow(c, 1.4);
  return pow(abs(c), 8.0);
}
`;

/** Adds drifting caustic light patterns (world-space, from above) to a standard material. */
export function addCaustics(mat: THREE.Material, strength: number): void {
  mat.onBeforeCompile = (shader) => {
    shader.uniforms.uTime = timeU;
    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', '#include <common>\nvarying vec3 vWPos;\nvarying vec3 vWNrm;')
      .replace(
        '#include <begin_vertex>',
        `#include <begin_vertex>
        vWPos = (modelMatrix * vec4(transformed, 1.0)).xyz;
        vWNrm = normalize(mat3(modelMatrix) * objectNormal);`,
      );
    shader.fragmentShader = shader.fragmentShader
      .replace(
        '#include <common>',
        `#include <common>
        uniform float uTime;
        varying vec3 vWPos;
        varying vec3 vWNrm;
        ${CAUSTIC_FN}`,
      )
      .replace(
        '#include <opaque_fragment>',
        `{
          vec2 cp = vWPos.xz * 0.45 + vec2(vWPos.y * 0.15, 0.0);
          float cs = causticPattern(cp, uTime * 0.45 + 10.0);
          cs = min(cs, 1.6) * 0.8 + 0.2 * causticPattern(cp * 1.7 + 3.0, uTime * 0.3);
          float up = clamp(vWNrm.y * 0.6 + 0.4, 0.0, 1.0);
          float depthFade = smoothstep(9.0, 0.0, vWPos.y);
          outgoingLight += vec3(0.55, 1.0, 0.9) * cs * up * depthFade * ${strength.toFixed(3)};
        }
        #include <opaque_fragment>`,
      );
  };
  mat.customProgramCacheKey = () => 'caustics' + strength.toFixed(3);
}

/** Bends instanced geometry (local y up) like a plant swaying in a current. */
export function addSway(mat: THREE.Material, amp: number): void {
  mat.onBeforeCompile = (shader) => {
    shader.uniforms.uTime = timeU;
    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', '#include <common>\nuniform float uTime;')
      .replace(
        '#include <begin_vertex>',
        `#include <begin_vertex>
        {
          float h = max(position.y, 0.0);
          vec3 ip = vec3(0.0);
          #ifdef USE_INSTANCING
            ip = vec3(instanceMatrix[3]);
          #endif
          float ph = ip.x * 0.6 + ip.z * 0.8;
          float s1 = sin(uTime * 1.3 + ph + h * 1.6);
          float s2 = cos(uTime * 1.0 + ph * 1.3 + h * 1.2);
          transformed.x += s1 * ${amp.toFixed(3)} * h * h;
          transformed.z += s2 * ${amp.toFixed(3)} * h * h * 0.7;
        }`,
      );
  };
  mat.customProgramCacheKey = () => 'sway' + amp.toFixed(3);
}

import * as THREE from 'three';
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
import { addCaustics, groundY, makeRand, paint } from './common';

const coralMat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.75, metalness: 0 });
addCaustics(coralMat, 0.9);

function finish(parts: THREE.BufferGeometry[]): THREE.BufferGeometry {
  const merged = mergeGeometries(parts, false);
  for (const p of parts) p.dispose();
  if (!merged) throw new Error('merge failed');
  return merged;
}

function mesh(g: THREE.BufferGeometry, m: THREE.Material): THREE.Mesh {
  const o = new THREE.Mesh(g, m);
  o.castShadow = true;
  o.receiveShadow = true;
  return o;
}

export function branchingCoral(seed: number, base: THREE.Color, tip: THREE.Color): THREE.Mesh {
  const rand = makeRand(seed);
  const parts: THREE.BufferGeometry[] = [];
  const maxDepth = 3;
  const up = new THREE.Vector3(0, 1, 0);

  const grow = (pos: THREE.Vector3, dir: THREE.Vector3, len: number, rad: number, depth: number): void => {
    const g = new THREE.CylinderGeometry(rad * 0.72, rad, len, 6, 1);
    g.translate(0, len / 2, 0);
    g.applyQuaternion(new THREE.Quaternion().setFromUnitVectors(up, dir));
    g.translate(pos.x, pos.y, pos.z);
    paint(g, base.clone().lerp(tip, depth / maxDepth));
    parts.push(g);
    const end = pos.clone().addScaledVector(dir, len * 0.95);
    if (depth === maxDepth) {
      const s = new THREE.SphereGeometry(rad * 0.85, 6, 5);
      s.translate(end.x, end.y, end.z);
      paint(s, tip);
      parts.push(s);
      return;
    }
    const n = rand() < 0.5 ? 2 : 3;
    for (let i = 0; i < n; i++) {
      const d = dir
        .clone()
        .add(new THREE.Vector3(rand() - 0.5, rand() * 0.2, rand() - 0.5).multiplyScalar(1.3))
        .add(new THREE.Vector3(0, 0.3, 0))
        .normalize();
      grow(end, d, len * 0.78, rad * 0.68, depth + 1);
    }
  };

  const roots = 5;
  for (let i = 0; i < roots; i++) {
    const a = (i / roots) * Math.PI * 2 + rand();
    const lean = 0.25 + rand() * 0.35;
    const dir = new THREE.Vector3(Math.cos(a) * lean, 1, Math.sin(a) * lean).normalize();
    grow(new THREE.Vector3(Math.cos(a) * 0.12, -0.05, Math.sin(a) * 0.12), dir, 0.55 + rand() * 0.2, 0.11, 0);
  }
  return mesh(finish(parts), coralMat);
}

export function brainCoral(seed: number, base: THREE.Color): THREE.Mesh {
  const rand = makeRand(seed);
  const ox = rand() * 10;
  const oz = rand() * 10;
  const g = new THREE.SphereGeometry(1, 72, 52);
  const pos = g.getAttribute('position');
  const col = new Float32Array(pos.count * 3);
  const dark = base.clone().multiplyScalar(0.45);
  const c = new THREE.Color();
  const v = new THREE.Vector3();
  for (let i = 0; i < pos.count; i++) {
    v.fromBufferAttribute(pos, i);
    const n = v.clone().normalize();
    const q = Math.sin(n.x * 7 + ox + Math.sin(n.y * 6 + oz) * 1.6 + Math.sin(n.z * 8) * 1.2) * Math.sin(n.z * 6 + n.y * 3 + oz);
    const groove = Math.pow(Math.abs(q), 0.5); // 0 in the groove, 1 on the ridge
    const r = 1 + 0.07 * groove;
    v.copy(n).multiplyScalar(r);
    v.y *= v.y < 0 ? 0.25 : 0.72;
    pos.setXYZ(i, v.x, v.y, v.z);
    c.copy(dark).lerp(base, 0.15 + 0.85 * groove);
    col[i * 3] = c.r;
    col[i * 3 + 1] = c.g;
    col[i * 3 + 2] = c.b;
  }
  g.setAttribute('color', new THREE.BufferAttribute(col, 3));
  g.computeVertexNormals();
  return mesh(g, coralMat);
}

let fanTex: THREE.CanvasTexture | null = null;
function fanTexture(): THREE.CanvasTexture {
  if (fanTex) return fanTex;
  const cv = document.createElement('canvas');
  cv.width = 256;
  cv.height = 256;
  const ctx = cv.getContext('2d');
  if (!ctx) throw new Error('2d context unavailable');
  ctx.clearRect(0, 0, 256, 256);
  ctx.strokeStyle = '#ffffff';
  ctx.lineCap = 'round';
  // radial ribs
  ctx.lineWidth = 6;
  for (let i = 0; i <= 18; i++) {
    const a = Math.PI + (i / 18) * Math.PI;
    ctx.beginPath();
    ctx.moveTo(128, 128);
    ctx.lineTo(128 + Math.cos(a) * 124, 128 + Math.sin(a) * 124);
    ctx.stroke();
  }
  // cross links
  ctx.lineWidth = 4;
  for (let r = 30; r < 124; r += 20) {
    ctx.beginPath();
    ctx.arc(128, 128, r, Math.PI, Math.PI * 2);
    ctx.stroke();
  }
  ctx.lineWidth = 8;
  ctx.beginPath();
  ctx.arc(128, 128, 120, Math.PI, Math.PI * 2);
  ctx.stroke();
  fanTex = new THREE.CanvasTexture(cv);
  fanTex.colorSpace = THREE.SRGBColorSpace;
  fanTex.anisotropy = 4;
  return fanTex;
}

export function fanCoral(color: number): THREE.Mesh {
  const g = new THREE.CircleGeometry(1, 56, 0, Math.PI);
  const pos = g.getAttribute('position');
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i);
    const y = pos.getY(i);
    pos.setZ(i, 0.12 * Math.sin(x * 3.2 + 0.5) + 0.08 * y * y);
  }
  g.computeVertexNormals();
  const m = new THREE.MeshStandardMaterial({
    map: fanTexture(),
    color,
    alphaTest: 0.5,
    side: THREE.DoubleSide,
    roughness: 0.8,
  });
  addCaustics(m, 0.8);
  const o = mesh(g, m);
  o.scale.set(1.1, 1.3, 1.1);
  return o;
}

export function tubeCoral(seed: number, base: THREE.Color, rim: THREE.Color): THREE.Mesh {
  const rand = makeRand(seed);
  const parts: THREE.BufferGeometry[] = [];
  const n = 8;
  const inside = new THREE.Color(0x1a0a18);
  for (let i = 0; i < n; i++) {
    const a = rand() * Math.PI * 2;
    const d = Math.sqrt(rand()) * 0.4;
    const h = 0.5 + rand() * 0.75;
    const r = 0.07 + rand() * 0.06;
    const tube = new THREE.CylinderGeometry(r, r * 0.8, h, 12, 1);
    tube.translate(0, h / 2, 0);
    paint(tube, base.clone().lerp(rim, rand() * 0.5));
    const cap = new THREE.CircleGeometry(r * 0.72, 12);
    cap.rotateX(-Math.PI / 2);
    cap.translate(0, h + 0.004, 0);
    paint(cap, inside);
    const both = finish([tube, cap]);
    both.rotateX((rand() - 0.5) * 0.4);
    both.rotateZ((rand() - 0.5) * 0.4);
    both.translate(Math.cos(a) * d, -0.05, Math.sin(a) * d);
    parts.push(both);
  }
  return mesh(finish(parts), coralMat);
}

const rockMat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.95, flatShading: true });
addCaustics(rockMat, 0.7);

export function rock(seed: number, tint: THREE.Color): THREE.Mesh {
  const rand = makeRand(seed);
  const g = new THREE.IcosahedronGeometry(1, 2);
  const pos = g.getAttribute('position');
  const key = new Map<string, number>();
  const col = new Float32Array(pos.count * 3);
  const c = new THREE.Color();
  const p1 = rand() * 6;
  const p2 = rand() * 6;
  const v = new THREE.Vector3();
  for (let i = 0; i < pos.count; i++) {
    v.fromBufferAttribute(pos, i);
    const k = `${v.x.toFixed(3)},${v.y.toFixed(3)},${v.z.toFixed(3)}`;
    let f = key.get(k);
    if (f === undefined) {
      f = 0.8 + 0.25 * Math.sin(v.x * 3 + p1) * Math.cos(v.z * 3 + p2) + 0.12 * Math.sin(v.y * 5 + p1 * 2);
      key.set(k, f);
    }
    v.multiplyScalar(f);
    v.y *= 0.65;
    pos.setXYZ(i, v.x, v.y, v.z);
    c.copy(tint).multiplyScalar(0.7 + 0.5 * (f - 0.6) + (rand() - 0.5) * 0.05);
    col[i * 3] = c.r;
    col[i * 3 + 1] = c.g;
    col[i * 3 + 2] = c.b;
  }
  g.setAttribute('color', new THREE.BufferAttribute(col, 3));
  g.computeVertexNormals();
  return mesh(g, rockMat);
}

export function buildReef(): THREE.Group {
  const reef = new THREE.Group();
  const rand = makeRand(77);
  const C = (hex: number): THREE.Color => new THREE.Color(hex);

  const place = (o: THREE.Object3D, x: number, z: number, s: number, sink = 0.05): void => {
    o.position.set(x, groundY(x, z) - sink * s, z);
    o.scale.multiplyScalar(s);
    o.rotation.y = rand() * Math.PI * 2;
    reef.add(o);
  };

  // central rock base
  place(rock(1, C(0x6a6a62)), 0, 0, 1.5, 0.3);
  place(rock(2, C(0x77705f)), -2.3, 1.2, 0.9, 0.2);
  place(rock(3, C(0x5f6a66)), 3.0, -0.8, 1.0, 0.25);
  place(rock(4, C(0x6e6a60)), 1.0, 4.4, 0.7, 0.2);

  // branching
  place(branchingCoral(11, C(0xe0561f), C(0xffc07a)), 0, 0.1, 1.7, 0);
  place(branchingCoral(12, C(0xd0307a), C(0xffa0d0)), -3.2, 1.8, 1.3, 0);
  place(branchingCoral(13, C(0xc9b21c), C(0xf3ff7a)), 3.5, -2.0, 1.4, 0);
  place(branchingCoral(14, C(0x7a38c8), C(0xd7a0ff)), 1.5, 3.6, 1.1, 0);
  place(branchingCoral(15, C(0xd6302a), C(0xff9a70)), -2.5, -3.5, 1.2, 0);

  // brain
  place(brainCoral(21, C(0xc9a85a)), 2.2, 0.9, 0.85);
  place(brainCoral(22, C(0x4ea06a)), -1.4, -1.3, 0.75);
  place(brainCoral(23, C(0xd04a9a)), 4.6, 2.5, 0.95);
  place(brainCoral(24, C(0x6cb0a0)), -4.8, -0.6, 1.0);

  // fans
  place(fanCoral(0xb050e0), -1.2, 2.5, 1.2, 0.1);
  place(fanCoral(0xff4a3a), 1.2, -2.5, 1.3, 0.1);
  place(fanCoral(0xe040a0), -5.0, 3.0, 1.4, 0.1);
  place(fanCoral(0x8a60ff), 5.5, -0.5, 1.2, 0.1);

  // tubes
  place(tubeCoral(31, C(0xf0c020), C(0xfff080)), 3.0, 3.0, 1.1, 0);
  place(tubeCoral(32, C(0x3a70e0), C(0x80d0ff)), -3.6, -2.0, 1.2, 0);
  place(tubeCoral(33, C(0xf07820), C(0xffc060)), 0.6, -4.6, 1.0, 0);

  // scattered outer reef
  const palette = [0xe0561f, 0xd0307a, 0xc9b21c, 0x7a38c8, 0xd6302a, 0x3a9ae0, 0x40c070];
  for (let i = 0; i < 16; i++) {
    const a = rand() * Math.PI * 2;
    const r = 8 + rand() * 9;
    const x = Math.cos(a) * r;
    const z = Math.sin(a) * r;
    const base = C(palette[Math.floor(rand() * palette.length)]);
    const tip = base.clone().lerp(C(0xffffff), 0.45);
    const t = i % 4;
    if (t === 0) place(branchingCoral(100 + i, base, tip), x, z, 1.2 + rand() * 0.9, 0);
    else if (t === 1) place(brainCoral(200 + i, base), x, z, 0.9 + rand() * 0.8);
    else if (t === 2) place(fanCoral(palette[Math.floor(rand() * palette.length)]), x, z, 1.2 + rand(), 0.1);
    else place(tubeCoral(300 + i, base, tip), x, z, 1.0 + rand() * 0.6, 0);
    if (rand() < 0.5) place(rock(400 + i, C(0x66675f)), x + 1.2, z - 0.8, 0.6 + rand() * 0.8, 0.2);
  }
  return reef;
}

import * as THREE from 'three';
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
import { addSway, groundY, makeRand, paint, timeU } from './common';

function setGradient(g: THREE.BufferGeometry, lo: THREE.Color, hi: THREE.Color, yMax: number): void {
  const pos = g.getAttribute('position');
  const col = new Float32Array(pos.count * 3);
  const c = new THREE.Color();
  for (let i = 0; i < pos.count; i++) {
    c.copy(lo).lerp(hi, Math.min(Math.max(pos.getY(i) / yMax, 0), 1));
    col[i * 3] = c.r;
    col[i * 3 + 1] = c.g;
    col[i * 3 + 2] = c.b;
  }
  g.setAttribute('color', new THREE.BufferAttribute(col, 3));
}

export function buildSeaweed(): THREE.InstancedMesh {
  const rand = makeRand(5);
  const g = new THREE.PlaneGeometry(0.16, 1, 1, 7);
  g.translate(0, 0.5, 0);
  const pos = g.getAttribute('position');
  for (let i = 0; i < pos.count; i++) pos.setX(i, pos.getX(i) * (1 - 0.75 * pos.getY(i)));
  setGradient(g, new THREE.Color(0x0e3d1c), new THREE.Color(0x8ab83a), 1);
  const m = new THREE.MeshStandardMaterial({ vertexColors: true, side: THREE.DoubleSide, roughness: 0.8 });
  addSway(m, 0.32);

  const clumps: { x: number; z: number; n: number; s: number }[] = [];
  for (let i = 0; i < 26; i++) {
    const a = rand() * Math.PI * 2;
    const r = 2.5 + Math.pow(rand(), 0.8) * 12;
    clumps.push({ x: Math.cos(a) * r, z: Math.sin(a) * r, n: 8 + Math.floor(rand() * 10), s: 0.8 + rand() * 1.3 });
  }
  const total = clumps.reduce((s, c) => s + c.n, 0);
  const im = new THREE.InstancedMesh(g, m, total);
  const d = new THREE.Object3D();
  const col = new THREE.Color();
  let k = 0;
  for (const c of clumps) {
    for (let i = 0; i < c.n; i++) {
      const x = c.x + (rand() - 0.5) * 1.2;
      const z = c.z + (rand() - 0.5) * 1.2;
      d.position.set(x, groundY(x, z) - 0.03, z);
      d.rotation.set(0, rand() * Math.PI, 0);
      d.scale.set(0.8 + rand() * 0.7, c.s * (0.6 + rand() * 0.8), 1);
      d.updateMatrix();
      im.setMatrixAt(k, d.matrix);
      col.setHSL(0.25 + rand() * 0.1, 0.55, 0.45 + rand() * 0.15);
      im.setColorAt(k, col);
      k++;
    }
  }
  im.instanceMatrix.needsUpdate = true;
  if (im.instanceColor) im.instanceColor.needsUpdate = true;
  im.frustumCulled = false;
  return im;
}

export function buildAnemones(): THREE.Group {
  const rand = makeRand(9);
  const group = new THREE.Group();
  const tg = new THREE.CylinderGeometry(0.012, 0.032, 0.5, 5, 4);
  tg.translate(0, 0.25, 0);
  setGradient(tg, new THREE.Color(0xa0206a), new THREE.Color(0xffd0f0), 0.5);
  const m = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.6 });
  addSway(m, 1.3);
  const baseMat = new THREE.MeshStandardMaterial({ color: 0x8a2a68, roughness: 0.7 });

  const spots: [number, number, number][] = [
    [-0.9, 0.4, 1.2],
    [2.0, -1.6, 1.0],
    [-3.2, -0.3, 1.3],
    [0.3, 2.2, 1.0],
    [4.2, 0.6, 1.2],
    [-1.8, -2.6, 1.1],
    [2.4, 4.6, 1.2],
    [-5.5, 2.0, 1.4],
  ];
  for (const [x, z, s] of spots) {
    const per = 46;
    const im = new THREE.InstancedMesh(tg, m, per);
    const d = new THREE.Object3D();
    for (let i = 0; i < per; i++) {
      const a = rand() * Math.PI * 2;
      const r = Math.sqrt(rand()) * 0.16;
      d.position.set(Math.cos(a) * r, 0.1, Math.sin(a) * r);
      d.rotation.set(0, 0, 0);
      d.rotateY(-a);
      d.rotateZ(-(0.15 + (r / 0.16) * 0.7 + rand() * 0.2));
      d.scale.setScalar(0.7 + rand() * 0.5);
      d.updateMatrix();
      im.setMatrixAt(i, d.matrix);
    }
    im.frustumCulled = false;
    const stalk = new THREE.Mesh(new THREE.CylinderGeometry(0.17, 0.22, 0.22, 14), baseMat);
    stalk.position.y = 0.05;
    const holder = new THREE.Group();
    holder.add(stalk, im);
    holder.position.set(x, groundY(x, z) - 0.04, z);
    holder.scale.setScalar(s);
    group.add(holder);
  }
  return group;
}

/* ------------------------------ fish ------------------------------ */

function fishGeometry(): THREE.BufferGeometry {
  const body = new THREE.SphereGeometry(0.5, 14, 10);
  body.scale(0.28, 0.42, 1);
  const tail = new THREE.ConeGeometry(0.24, 0.4, 4);
  tail.rotateX(Math.PI / 2);
  tail.scale(0.12, 1, 1);
  tail.translate(0, 0, -0.65);
  const dorsal = new THREE.ConeGeometry(0.12, 0.3, 3);
  dorsal.scale(0.15, 1, 1.6);
  dorsal.translate(0, 0.3, 0.02);
  const parts = [body, tail, dorsal];
  for (const p of parts) {
    const pos = p.getAttribute('position');
    const col = new Float32Array(pos.count * 3);
    for (let i = 0; i < pos.count; i++) {
      // darker back, pale belly
      const t = Math.min(Math.max(pos.getY(i) / 0.4 * 0.5 + 0.5, 0), 1);
      const v = 1.15 - 0.55 * t;
      col[i * 3] = v;
      col[i * 3 + 1] = v;
      col[i * 3 + 2] = v;
    }
    p.setAttribute('color', new THREE.BufferAttribute(col, 3));
  }
  const g = mergeGeometries(parts, false);
  for (const p of parts) p.dispose();
  if (!g) throw new Error('fish merge failed');
  return g;
}

function fishMesh(count: number, speed: number): THREE.InstancedMesh {
  const g = fishGeometry();
  const phase = new Float32Array(count);
  const r = makeRand(count * 31 + 7);
  for (let i = 0; i < count; i++) phase[i] = r() * 6.28;
  g.setAttribute('aPhase', new THREE.InstancedBufferAttribute(phase, 1));
  const m = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.35, metalness: 0.25 });
  m.onBeforeCompile = (shader) => {
    shader.uniforms.uTime = timeU;
    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', '#include <common>\nuniform float uTime;\nattribute float aPhase;')
      .replace(
        '#include <begin_vertex>',
        `#include <begin_vertex>
        {
          float back = clamp(-position.z + 0.1, 0.0, 1.0);
          transformed.x += sin(uTime * ${speed.toFixed(2)} + aPhase - position.z * 4.0) * 0.14 * back * back;
        }`,
      );
  };
  m.customProgramCacheKey = () => 'fish' + speed.toFixed(2);
  const im = new THREE.InstancedMesh(g, m, count);
  im.frustumCulled = false;
  return im;
}

export interface Fish {
  school: THREE.InstancedMesh;
  big: THREE.InstancedMesh;
  update(t: number): void;
}

export function buildFish(): Fish {
  const SCHOOL = 48;
  const rand = makeRand(21);
  const school = fishMesh(SCHOOL, 11);
  const offs: THREE.Vector3[] = [];
  const ph: number[] = [];
  const c = new THREE.Color();
  for (let i = 0; i < SCHOOL; i++) {
    const u = new THREE.Vector3(rand() - 0.5, (rand() - 0.5) * 0.6, rand() - 0.5).multiplyScalar(4.2);
    offs.push(u);
    ph.push(rand() * 6.28, rand() * 6.28, rand() * 6.28);
    const blue = rand() < 0.25;
    if (blue) c.setRGB(0.25 + rand() * 0.1, 0.55, 1.0);
    else c.setRGB(1.0, 0.7 + rand() * 0.2, 0.1 + rand() * 0.1);
    school.setColorAt(i, c);
  }
  if (school.instanceColor) school.instanceColor.needsUpdate = true;

  const big = fishMesh(4, 6);
  // [colour, scale xyz, centre xz, radii, height, bob, angular speed, phase]
  const bigDefs = [
    { col: [1.0, 0.45, 0.05], sc: [1.0, 1.0, 1.0], cx: 0, cz: 0, rx: 8.0, rz: 6.0, y: 2.2, w: 0.2, p: 0 },
    { col: [0.1, 0.3, 1.0], sc: [0.8, 1.5, 0.9], cx: 1, cz: -1, rx: 5.5, rz: 7.5, y: 1.6, w: -0.16, p: 2 },
    { col: [0.85, 0.95, 1.0], sc: [1.3, 1.3, 1.5], cx: -2, cz: 1, rx: 10.0, rz: 4.5, y: 3.4, w: 0.12, p: 4 },
    { col: [1.0, 0.9, 0.15], sc: [0.9, 1.7, 0.9], cx: 0, cz: 1, rx: 4.0, rz: 4.0, y: 1.5, w: -0.27, p: 1 },
  ];
  bigDefs.forEach((b, i) => big.setColorAt(i, c.setRGB(b.col[0], b.col[1], b.col[2])));
  if (big.instanceColor) big.instanceColor.needsUpdate = true;

  const d = new THREE.Object3D();
  const p0 = new THREE.Vector3();
  const p1 = new THREE.Vector3();

  const schoolPos = (i: number, t: number, out: THREE.Vector3): void => {
    const cx = 6.5 * Math.sin(t * 0.17) + 2 * Math.sin(t * 0.41 + 1);
    const cz = 5.5 * Math.cos(t * 0.13) + 1.5 * Math.cos(t * 0.37);
    const cy = 2.9 + 0.7 * Math.sin(t * 0.23);
    const o = offs[i];
    out.set(
      cx + o.x + 0.5 * Math.sin(t * 0.8 + ph[i * 3]),
      cy + o.y + 0.25 * Math.sin(t * 0.6 + ph[i * 3 + 1]),
      cz + o.z + 0.5 * Math.cos(t * 0.7 + ph[i * 3 + 2]),
    );
  };

  const bigPos = (i: number, t: number, out: THREE.Vector3): void => {
    const b = bigDefs[i];
    const a = b.w * t + b.p;
    const x = b.cx + b.rx * Math.cos(a);
    const z = b.cz + b.rz * Math.sin(a);
    out.set(x, groundY(x, z) + b.y + 0.4 * Math.sin(t * 0.4 + b.p), z);
  };

  const aim = (s: number, ix: number, im: THREE.InstancedMesh, sx: number, sy: number, sz: number): void => {
    d.position.copy(p0);
    d.lookAt(p1);
    d.scale.set(sx * s, sy * s, sz * s);
    d.updateMatrix();
    im.setMatrixAt(ix, d.matrix);
  };

  return {
    school,
    big,
    update(t: number) {
      for (let i = 0; i < SCHOOL; i++) {
        schoolPos(i, t, p0);
        schoolPos(i, t + 0.15, p1);
        aim(0.42, i, school, 1, 1, 1);
      }
      school.instanceMatrix.needsUpdate = true;
      for (let i = 0; i < bigDefs.length; i++) {
        bigPos(i, t, p0);
        bigPos(i, t + 0.15, p1);
        const b = bigDefs[i];
        aim(1.0, i, big, b.sc[0], b.sc[1], b.sc[2]);
      }
      big.instanceMatrix.needsUpdate = true;
    },
  };
}

