/* water backdrop: horizon matches fog, brighter towards the surface */
const hex3 = (h: number): THREE.Vector3 => new THREE.Vector3((h >> 16) & 255, (h >> 8) & 255, h & 255).divideScalar(255);
const sky = new THREE.Mesh(
