  const light = new THREE.Color(0xe6d3a2);
  const dark = new THREE.Color(0xa8946a);
  const c = new THREE.Color();
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i);
    const z = pos.getZ(i);
