    pos.setY(i, h);
    const w = x * 0.9 + z * 0.35 + 1.3 * Math.sin(z * 0.3 + x * 0.12);
    const crest = 0.5 + 0.5 * Math.sin(w * 2.6);
    const speck = 0.5 + 0.5 * Math.sin(x * 7.1) * Math.sin(z * 6.3);
    c.copy(dark).lerp(light, 0.25 + 0.6 * crest + 0.15 * speck);
    col[i * 3] = c.r;
